-- Criação do Banco de Dados
CREATE DATABASE IF NOT EXISTS nba_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nba_db;

-- Estrutura da tabela `equipe`
CREATE TABLE IF NOT EXISTS `equipe` (
  `equipe` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`equipe`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Estrutura da tabela `temporada`
CREATE TABLE IF NOT EXISTS `temporada` (
  `ano` VARCHAR(45) NOT NULL,
  PRIMARY KEY (`ano`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Estrutura da tabela `jogos`
CREATE TABLE IF NOT EXISTS `jogos` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `placar_casa` INT DEFAULT NULL,
  `placar_visitante` INT DEFAULT NULL,
  `data` DATETIME DEFAULT NULL,
  `round` INT DEFAULT NULL,
  `stage` INT DEFAULT NULL,
  `ano` VARCHAR(45) NOT NULL,
  `equipe_casa` VARCHAR(100) NOT NULL,
  `equipe_visitante` VARCHAR(100) NOT NULL,
  `estatisticas_casa` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `estatisticas_visitantes` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  PRIMARY KEY (`id`),
  FOREIGN KEY (`ano`) REFERENCES `temporada` (`ano`),
  FOREIGN KEY (`equipe_casa`) REFERENCES `equipe` (`equipe`),
  FOREIGN KEY (`equipe_visitante`) REFERENCES `equipe` (`equipe`),
  CONSTRAINT `jogos_chk_1` CHECK (json_valid(`estatisticas_casa`)),
  CONSTRAINT `jogos_chk_2` CHECK (json_valid(`estatisticas_visitantes`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

